const legs='<g data-part="legs"><path d="M100 273L95 373" stroke="'+outline+'" stroke-width="33" stroke-linecap="round"/><path d="M140 273L147 373" stroke="'+outline+'" stroke-width="33" stroke-linecap="round"/><path d="M100 273L95 373" stroke="'+c.legs+'" stroke-width="27" stroke-linecap="round"/><path d="M140 273L147 373" stroke="'+c.legs+'" stroke-width="27" stroke-linecap="round"/><path data-part="left-foot" d="M83 369h24v23H73q-4-14 10-23Z" fill="'+outline+'"/><path data-part="right-foot" d="M136 369h24q17 9 12 23h-36Z" fill="'+outline+'"/></g>';
