const configFields=['name','role','environment','greeting','tone','duties','knowledge','workflow','handoff'];let workspaceList=[],templateList=[],revision=1;function fillConfig(p){for(const field of configFields)$('config-'+field).value=p[field]||'';$('template').value=p.templateId||p.id;revision=p.revision||1;}function readConfig(){return Object.fromEntries([...configFields.map(f=>[f,$('config-'+f).value]),['templateId',$('template').value],['revision',revision]]);}async function loadWorkspaces(selected=site){workspaceList=await api('workspaces');$('site').replaceChildren(...workspaceList.map(p=>new Option(p.name+' · '+p.role,p.id)));site=workspaceList.some(p=>p.id===selected)?selected:workspaceList[0].id;$('site').value=site;fillConfig(workspaceList.find(p=>p.id===site));const current=workspaceList.find(p=>p.id===site);$('workspace-caption').textContent=current.name+' · '+current.role;if(voiceInitialized)restoreVoiceConfig();await people();if(typeof refreshModel==='function'&&typeof modelLoadEpoch!=='undefined')refreshModel();}
