var modelLoadedSite=null,modelRevision=0,modelProviders={},modelSavedProfiles={},modelConnections=[],modelLoadEpoch=0;async function loadModel(){const target=site,token=++modelLoadEpoch;const c=await api('model-config');if(target!==site||token!==modelLoadEpoch)return;modelLoadedSite=site;modelProviders=c.providers;modelSavedProfiles=c.profiles||{};modelConnections=c.connections||[];renderModelPlans(c);modelRevision=c.revision;$('model-provider').value=c.provider;$('model-url').value=c.baseUrl;$('model-name').value=c.model;if($('model-response-mode'))$('model-response-mode').value=c.responseMode||'fast';$('model-key').value='';$('model-clear-key').checked=false;$('model-cloud-consent').checked=c.cloudConsent;$('model-memory-consent').checked=c.cloudMemoryConsent;$('model-status').textContent='已读取本场所配置 · '+(c.hasKey?'后台已保存密钥':'未保存密钥');$('active-model-caption').textContent='对话模型：'+modelProviders[c.provider].label+(c.model?' / '+c.model:'');}
