async function streamInteraction(message,token){const {readChatStream,takeSentences}=await import('/chat-stream.js');if(token!==epoch)return;const controller=new AbortController();activeChatRequest=controller;const started=performance.now();let text='',pending='',firstMs=null,speechQueuedMs=null,voiceTail=Promise.resolve();const speaking=voiceInitialized&&($('auto-narrate').checked||$('interaction-mode')?.value==='voice');const releaseBarge=speaking?await window.beginBargeMonitor?.():null;$('reply').textContent='';$('state').textContent='正在生成回答…';$('active-model-caption').textContent='正在请求当前模型 · 文字逐步显示';const say=sentence=>{if(!speaking)return;voiceTail=voiceTail.then(async()=>{if(controller.signal.aborted||token!==epoch)throw new DOMException('已停止','AbortError');speechQueuedMs??=performance.now()-started;await playNarration(sentence,{keepEpoch:true,enqueueOnly:streamingVoice});});voiceTail.catch(()=>{});};try{const response=await fetch('/api/chat-stream?site='+encodeURIComponent(site),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:message,sessionId:personalSession||undefined,history:chatHistory}),signal:controller.signal});const result=await readChatStream(response,{signal:controller.signal,onDelta:part=>{if(token!==epoch)throw new DOMException('已停止','AbortError');firstMs??=performance.now()-started;text+=part;$('reply').textContent=text;pending+=part;const ready=takeSentences(pending);pending=ready.pending;for(const sentence of ready.sentences)say(sentence);if($('latency-status'))$('latency-status').textContent='首批回答文字：'+(firstMs/1000).toFixed(2)+'秒 · 正在继续生成';}});if(result.mode==='guided'){if(token===epoch)await showGuided(result);return;}for(const sentence of takeSentences(pending,true).sentences)say(sentence);if(token!==epoch)return;let sources=document.getElementById('live-search-sources');if(!sources){sources=document.createElement('div');sources.id='live-search-sources';$('reply').after(sources);}sources.replaceChildren();if(result.search){const label=document.createElement('p');label.textContent=result.search.notice;sources.append(label);for(const item of result.search.results){const a=document.createElement('a');a.textContent='['+item.id+'] '+item.title;a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';sources.append(a,document.createElement('br'));}}chatHistory.push({role:'user',content:message.slice(0,1000)},{role:'assistant',content:result.text.slice(0,1000)});chatHistory=chatHistory.slice(-6);$('active-model-caption').textContent=result.mode==='real'?'实际模型 · '+result.provider+' / '+result.model+' · '+(result.responseMode==='deep'?'深度思考':'快速回复'):'演示模型 · 固定模板';if($('latency-status'))$('latency-status').textContent=($('latency-status').dataset.inputTiming?$('latency-status').dataset.inputTiming+'；':'')+'首批文字 '+((firstMs||0)/1000).toFixed(2)+'秒；完整文字 '+((performance.now()-started)/1000).toFixed(2)+'秒'+(speechQueuedMs!==null?'；第一句进入声音生成 '+(speechQueuedMs/1000).toFixed(2)+'秒':'')+'（从识别完成后计时）';await voiceTail;if(speaking&&streamingVoice)await pcmPlayer.drain(controller.signal);if(token===epoch){$('avatar').className='';$('state').textContent=speaking?'回答与朗读已完成':'文字回答已完成';}}catch(e){controller.abort();stopNarration();if(e.name!=='AbortError'&&token===epoch){$('reply').textContent='本次未能回答：'+e.message;$('state').textContent='对话服务调用失败，请检查模型设置';$('active-model-caption').textContent='模型调用失败 · 未生成回答';}throw e;}finally{releaseBarge?.();if(activeChatRequest===controller)activeChatRequest=null;}}

